using System.ComponentModel.DataAnnotations; using Microsoft.AspNetCore.Mvc; namespace AshishPortfolio.Api.Controllers; public record ContactRequest([property:Required,StringLength(80,MinimumLength=2)]string Name,[property:Required,EmailAddress,StringLength(200)]string Email,[property:Required,StringLength(2000,MinimumLength=10)]string Message); [ApiController][Route("api/contact")] public class ContactController(ILogger<ContactController> logger):ControllerBase { [HttpPost] public IActionResult Submit(ContactRequest request){logger.LogInformation("Portfolio contact from {Name} ({Email}); message length {Length}",request.Name,request.Email,request.Message.Length);return Accepted(new{success=true,message="Your message has been received."});} }
